  'ProRes 母带体积较大，仅本机渲染；适合调色或交给达芬奇继续剪。网发请用 H.264。': 'Bản dựng gốc ProRes có dung lượng lớn, chỉ kết xuất trên máy; phù hợp để chỉnh màu hoặc tiếp tục dựng trong DaVinci. Dùng H.264 khi đăng lên mạng.',
