  '把时间线上的视频、音轨与字幕写入本地草稿库，用剪映或 CapCut 打开即可继续剪辑。': 'Ghi video, rãnh âm thanh và phụ đề trên dòng thời gian vào thư viện bản nháp cục bộ; mở bằng CapCut để tiếp tục dựng.',
  '草稿名称': 'Tên bản nháp',
