  'MiniMax 海螺': 'MiniMax Hailuo',
  '选择 Fal.ai 作为默认厂商，然后选择模型。聊天中指定的模型优先于此默认值。': 'Chọn Fal.ai làm nhà cung cấp mặc định, sau đó chọn mô hình. Mô hình được chỉ định trong cuộc trò chuyện sẽ được ưu tiên hơn giá trị mặc định này.',
  '对话与工具调用的核心，未配置无法对话。': 'Thành phần cốt lõi cho trò chuyện và gọi công cụ; chưa cấu hình thì không thể trò chuyện.',
  'submit_image · 文生图 / 图生图，任一厂商即可。': 'submit_image · tạo ảnh từ văn bản / biến đổi ảnh, dùng nhà cung cấp bất kỳ.',
  'submit_voice · 文字转配音，任一厂商即可。': 'submit_voice · chuyển văn bản thành giọng đọc, dùng nhà cung cấp bất kỳ.',
  'submit_video · 文 / 图生视频，任一厂商即可。': 'submit_video · tạo video từ văn bản/ảnh, dùng nhà cung cấp bất kỳ.',
  'submit_music · 文字 / 成片生成配乐，任一厂商即可。': 'submit_music · tạo nhạc từ văn bản/video thành phẩm, dùng nhà cung cấp bất kỳ.',
  'search_stock_media · 搜索可商用图片 / 视频素材。': 'search_stock_media · tìm hình ảnh/video có thể sử dụng thương mại.',
  'transcribe_track · 词级字幕、清口水、删词。': 'transcribe_track · phụ đề từng từ, làm sạch lời nói, xóa từ.',
  '素材的本地保存目录，与可选的 R2 云备份。': 'Thư mục lưu tư liệu cục bộ và tùy chọn sao lưu đám mây R2.',
  'run_code · 云端沙箱运行 ffmpeg / node / python。': 'run_code · chạy ffmpeg / node / python trong hộp cát đám mây.',
  'web_browser · 抓取网页内容供 Agent 参考。': 'web_browser · lấy nội dung web để tác nhân AI tham khảo.',
  '继承模型目录': 'Kế thừa danh mục mô hình',
