  '留空会使用内置模型目录；未知模型使用保守回退值。': 'Để trống sẽ dùng danh mục mô hình tích hợp; mô hình không xác định dùng giá trị dự phòng an toàn.',
  'API Base URL': 'URL cơ sở của API',
