  '豆包': 'Doubao',
  '可灵': 'Kling',
  '{name}（未配置）': '{name} (chưa cấu hình)',
  '选中未配置的厂商时，Agent 会回退为先询问。': 'Khi chọn nhà cung cấp chưa cấu hình, tác nhân AI sẽ hỏi trước khi thực hiện.',
  'AssemblyAI（云端）': 'AssemblyAI (đám mây)',
