  '删除当前口播中的填充词，并保持字幕与画面同步': 'Xóa từ đệm trong lời thoại hiện tại và giữ phụ đề đồng bộ với hình ảnh',
  '删除当前时间线中的静音停顿，并收紧空隙': 'Xóa khoảng lặng trong dòng thời gian hiện tại và thu hẹp khoảng trống',
  '把当前口播剪成节奏紧凑的跳切版本': 'Cắt lời thoại hiện tại thành phiên bản cắt nhảy nhịp nhanh',
  '为当前口播生成并应用同步字幕': 'Tạo và áp dụng phụ đề đồng bộ cho lời thoại hiện tại',
  '将当前时间线中的人声音量标准化': 'Chuẩn hóa âm lượng giọng nói trên dòng thời gian hiện tại',
  '将当前工程转换为 9:16 竖屏，并调整主要画面构图': 'Chuyển dự án hiện tại thành video dọc 9:16 và điều chỉnh bố cục hình ảnh chính',
  '标题、数据卡与转场动效': 'Tiêu đề, thẻ dữ liệu và hoạt ảnh chuyển cảnh',
  '提炼高光并重排为短视频': 'Chắt lọc khoảnh khắc nổi bật và sắp xếp thành video ngắn',
  '围绕卖点组织脚本和镜头': 'Xây dựng kịch bản và cảnh quay xoay quanh điểm bán hàng',
  '从概念生成镜头与声音': 'Tạo cảnh quay và âm thanh từ ý tưởng',
  '把主题整理成清晰讲解': 'Biên tập chủ đề thành phần giải thích rõ ràng',
  '精剪当前口播：去掉无效停顿和赘词，并生成同步字幕': 'Dựng kỹ lời thoại hiện tại: bỏ khoảng dừng và từ thừa, đồng thời tạo phụ đề đồng bộ',
  '为当前内容设计动态包装，包含标题、信息卡和转场动效': 'Thiết kế bộ đồ họa chuyển động cho nội dung hiện tại, gồm tiêu đề, thẻ thông tin và hoạt ảnh chuyển cảnh',
  '从当前长视频中提炼高光，重排成适合发布的短视频': 'Chắt lọc điểm nổi bật từ video dài hiện tại và sắp xếp thành video ngắn phù hợp đăng tải',
  '围绕产品卖点组织脚本和镜头，制作一支产品宣传短片': 'Xây dựng kịch bản và cảnh quay quanh điểm bán hàng của sản phẩm để làm video quảng bá ngắn',
  '根据我的概念策划一支 AI 影像，补全镜头、声音和节奏': 'Dựa trên ý tưởng của tôi để lên kế hoạch video AI, bổ sung cảnh quay, âm thanh và nhịp điệu',
  '把主题整理成结构清晰、带字幕和视觉提示的讲解视频': 'Biên tập chủ đề thành video giải thích có cấu trúc rõ ràng, phụ đề và gợi ý hình ảnh',
  '拉焦中': 'Đang kéo nét',
  '推轨道车': 'Đẩy xe trượt máy quay',
  '检查片门': 'Kiểm tra cửa màn trập',
  '打板儿': 'Vỗ bảng cảnh',
  '同期声走起': 'Chạy âm thanh đồng bộ',
  '走位走位': 'Vào vị trí',
  '卡点卡点': 'Bám nhịp',
  '架灯架灯': 'Dựng đèn',
