  '场景检测只支持已经保存到本机素材库的视频': 'Phát hiện cảnh chỉ hỗ trợ video đã lưu trong thư viện tư liệu cục bộ',
  '当前轨道已锁定，无法应用场景检测结果': 'Rãnh hiện tại đã khóa, không thể áp dụng kết quả phát hiện cảnh',
  '切点证据': 'Bằng chứng điểm cắt',
