  '检测完成后会显示切点前后的画面对比': 'Sau khi phát hiện xong sẽ hiển thị so sánh hình ảnh trước/sau điểm cắt',
  '正在读取画面变化…': 'Đang đọc thay đổi hình ảnh…',
