  '已导出 {file}({n} 条内容)——可直接上传资源网站': 'Đã xuất {file} ({n} nội dung) — có thể tải trực tiếp lên trang web tài nguyên',
  '已保存到资源库({n} 条内容)，可在对应分类直接使用': 'Đã lưu vào thư viện ({n} nội dung), có thể dùng trực tiếp trong danh mục tương ứng',
  '保存失败：{message}': 'Lưu thất bại: {message}',
  '选择创作工作流会约束 Agent 的规划与工具调用；激活后下一条消息按该工作流执行。': 'Chọn quy trình sáng tạo sẽ định hướng kế hoạch và gọi công cụ của tác nhân AI; sau khi kích hoạt, tin nhắn tiếp theo sẽ chạy theo quy trình đó.',
  '当前：{name}': 'Hiện tại: {name}',
  '点击取消创作模式，回到自由创作': 'Nhấp để hủy chế độ sáng tạo và quay lại sáng tạo tự do',
  '提示：也可在聊天输入框用 /skill:名称 快速激活，或用「技能创作器」创建自己的技能。': 'Gợi ý: có thể nhập /skill:tên trong ô trò chuyện để kích hoạt nhanh, hoặc dùng “Trình tạo kỹ năng” để tạo kỹ năng riêng.',
  'Anthropic 官方 CLI，Claude 订阅用户直连。': 'CLI chính thức của Anthropic, kết nối trực tiếp cho người dùng gói Claude.',
  'OpenAI CLI，通过环境变量携带令牌。': 'OpenAI CLI, truyền mã truy cập qua biến môi trường.',
  '写入 ~/.cursor/mcp.json 的全局配置。': 'Ghi cấu hình toàn cục vào ~/.cursor/mcp.json.',
  '写入 ~/.gemini/antigravity/mcp_config.json。': 'Ghi vào ~/.gemini/antigravity/mcp_config.json.',
  '写入 ~/.qoder/settings.json，国内版同时写 ~/.qoder-cn。': 'Ghi vào ~/.qoder/settings.json, bản nội địa đồng thời ghi vào ~/.qoder-cn.',
  '千问办公': 'Qwen Office',
  '自定义 MCP 只存在应用内，复制 JSON 后在连接器里粘贴。': 'MCP tùy chỉnh chỉ tồn tại trong ứng dụng, hãy sao chép JSON rồi dán vào bộ kết nối.',
  '复制失败，请手动选择配置文本。': 'Sao chép thất bại, hãy chọn văn bản cấu hình thủ công.',
  '已写入 {paths}': 'Đã ghi vào {paths}',
  '已写入 {paths}。请完全退出并重新打开 Codex，令牌才会生效。': 'Đã ghi vào {paths}. Hãy thoát hoàn toàn và mở lại Codex để mã truy cập có hiệu lực.',
  '连接后重启对应客户端生效；Codex 需新开终端使环境变量生效。': 'Khởi động lại ứng dụng tương ứng sau khi kết nối để có hiệu lực; Codex cần mở cửa sổ dòng lệnh mới để biến môi trường có hiệu lực.',
  '目标配置文件不是有效 JSON，为避免覆盖未写入。': 'Tệp cấu hình đích không phải JSON hợp lệ, không ghi để tránh ghi đè.',
  '写入配置文件失败。': 'Ghi tệp cấu hình thất bại.',
  '执行 codex mcp add 失败。': 'Thực thi codex mcp add thất bại.',
  '已在 Codex 注册，但令牌未能保存为 Windows 用户环境变量，连接未完成。': 'Đã đăng ký trong Codex nhưng không thể lưu mã truy cập vào biến môi trường người dùng Windows, kết nối chưa hoàn tất.',
  'OpenChatCut 暴露一个 Streamable HTTP MCP 端点。Claude Code / Codex / Cursor 等外部 Agent 接入后,与内置 Agent 共用同一套编辑工具,可直接读写当前工程。': 'OpenChatCut cung cấp điểm kết nối MCP Streamable HTTP. Sau khi Claude Code / Codex / Cursor hoặc tác nhân AI bên ngoài kết nối, chúng dùng chung bộ công cụ chỉnh sửa với tác nhân AI tích hợp và có thể đọc/ghi trực tiếp dự án hiện tại.',
  '内置 Agent 会先生成可预览的修改提案，由你应用或拒绝；外部 MCP 使用独立编辑会话，manual 模式等待审核，auto 模式在 review 时直接应用。两者都只通过 EditorCore 命令修改工程。': 'Tác nhân AI tích hợp tạo đề xuất có thể xem trước để bạn áp dụng hoặc từ chối; MCP bên ngoài dùng phiên chỉnh sửa riêng, chế độ thủ công chờ duyệt, chế độ tự động áp dụng trực tiếp khi duyệt. Cả hai chỉ sửa dự án qua lệnh EditorCore.',
  '打开 设置 → Agent 模型 → Agent 大脑 → OpenAI，填写本地或兼容服务的 API URL 和模型；按服务选择 Responses API 或 Chat Completions API，再点“测试并读取模型”。仅在服务要求时填写 API Key。': 'Mở Cài đặt → Mô hình tác nhân AI → Bộ não tác nhân AI → OpenAI, nhập URL API và mô hình của dịch vụ cục bộ hoặc tương thích; chọn Responses API hoặc Chat Completions API theo dịch vụ, rồi nhấp “Kiểm tra và lấy danh sách mô hình”. Chỉ nhập khóa API khi dịch vụ yêu cầu.',
