  '正在读取 MCP 连接令牌…': 'Đang đọc mã truy cập kết nối MCP…',
  '无法读取 MCP 连接令牌，请从受信任的编辑器窗口重试。': 'Không thể đọc mã truy cập kết nối MCP, hãy thử lại từ cửa sổ trình chỉnh sửa đáng tin cậy.',
  'MCP 端点始终要求 Bearer 令牌。令牌在首次启动时生成并保存在本机，重启后保持不变，配置一次即可持续使用；OPENCHATCUT_MCP_TOKEN 环境变量可覆盖。令牌只在当前受信任编辑器会话中显示，不写入工程、聊天或浏览器存储。': 'Điểm kết nối MCP luôn yêu cầu mã Bearer. Mã được tạo khi khởi động lần đầu và lưu trên máy, giữ nguyên sau khi khởi động lại nên chỉ cần cấu hình một lần; biến môi trường OPENCHATCUT_MCP_TOKEN có thể ghi đè. Mã chỉ hiển thị trong phiên trình chỉnh sửa đáng tin cậy hiện tại, không ghi vào dự án, trò chuyện hoặc bộ nhớ trình duyệt.',
  '设置 → 连接器 → 添加自定义连接器,粘贴上面的端点地址即可。': 'Vào Cài đặt → Bộ kết nối → Thêm bộ kết nối tùy chỉnh, rồi dán địa chỉ điểm kết nối ở trên.',
  '端点默认仅监听本机;对外暴露时请配置 OPENCHATCUT_MCP_TOKEN 鉴权。桌面端 5199 端口被占用时会回退随机端口,以启动日志与本页地址为准。': 'Mặc định điểm kết nối chỉ lắng nghe trên máy; khi mở ra ngoài hãy cấu hình xác thực OPENCHATCUT_MCP_TOKEN. Nếu cổng 5199 trên bản máy tính bị chiếm, hệ thống sẽ chuyển sang cổng ngẫu nhiên; hãy dùng nhật ký khởi động và địa chỉ trên trang này.',
