  '补全': 'Bổ sung',
  '桌面引擎已就绪；补全浏览器引擎文件，供桌面推理失败时回退': 'Bộ máy trên máy tính đã sẵn sàng; hãy tải bổ sung các tệp bộ máy trình duyệt để dùng khi suy luận trên máy tính thất bại',
  '模型按需下载到本机，不随应用打包。首次使用或下载模型时自动加速下载。': 'Mô hình được tải xuống máy theo nhu cầu, không đóng gói cùng ứng dụng. Tự tăng tốc tải khi dùng lần đầu hoặc tải mô hình.',
  '桌面原生推理加速': 'Tăng tốc suy luận trực tiếp trên máy tính',
  '启用后，转写使用 macOS Metal 或原生 CPU；画面语义、节拍与音乐语义模型自动选择 Windows DirectML、Linux CUDA、macOS CoreML 或浏览器 WebGPU；失败时回退 CPU 或浏览器引擎。': 'Khi bật, chép lời dùng macOS Metal hoặc CPU trực tiếp; mô hình ngữ nghĩa hình ảnh, nhịp và âm nhạc tự chọn Windows DirectML, Linux CUDA, macOS CoreML hoặc WebGPU trên trình duyệt; khi thất bại sẽ chuyển sang CPU hoặc bộ máy chạy trên trình duyệt.',
  'WebGPU 转写加速': 'Tăng tốc chép lời WebGPU',
  '删除静音（本地 VAD）': 'Xóa khoảng lặng (VAD cục bộ)',
  '启用后，Agent 的删除静音用本机 Silero VAD 判定语音区间，只删除确认无人说话的片段；关闭时不执行删除。模型随应用内置，无需下载。': 'Khi bật, tác nhân AI dùng Silero VAD trên máy để xác định vùng có tiếng nói và chỉ xóa đoạn chắc chắn không ai nói; khi tắt sẽ không xóa. Mô hình tích hợp sẵn, không cần tải.',
