  '选中的模型需已下载；未选择时按设备内存自动挑选（内存 ≥6GB 用 Small，否则 Base）。': 'Mô hình đã chọn phải được tải xuống; nếu chưa chọn, tự chọn theo dung lượng bộ nhớ thiết bị (≥6GB dùng Small, ngược lại Base).',
